distances.reserve(points.size());

for (size_t i = 0; i < points.size(); ++i) {
    double dx = points[i].x - searchPoint.x;
    double dy = points[i].y - searchPoint.y;
    double dz = points[i].z - searchPoint.z;
    double squaredDistance = dx * dx + dy * dy + dz * dz;
    distances.emplace_back(squaredDistance, i);
}

// Sort by squared distance (ascending)
std::sort(distances.begin(), distances.end(), [](const auto& a, const auto& b) {
    return a.first < b.first;
});

// Extract top k indices
for (size_t i = 0; i < k && i < distances.size(); ++i) {
    result.push_back(distances[i].second);
}

return result;

